using FluentValidation; using MediatR; using Microsoft.EntityFrameworkCore; using InventorySystem.Application.Interfaces;
namespace InventorySystem.Application.Features.Products.Commands;
public record UpdateProductCommand(int Id,string Name,string SKU,string? Barcode,string? Description,decimal PurchasePrice,decimal SellingPrice,int MinimumStock,int CategoryId) : IRequest;
public class UpdateProductCommandValidator : AbstractValidator<UpdateProductCommand> { public UpdateProductCommandValidator(){ RuleFor(x=>x.Id).GreaterThan(0); RuleFor(x=>x.Name).NotEmpty().MaximumLength(200); RuleFor(x=>x.SKU).NotEmpty().MaximumLength(50); RuleFor(x=>x.PurchasePrice).GreaterThanOrEqualTo(0); RuleFor(x=>x.SellingPrice).GreaterThanOrEqualTo(0); RuleFor(x=>x.MinimumStock).GreaterThanOrEqualTo(0); RuleFor(x=>x.CategoryId).GreaterThan(0); } }
public class UpdateProductCommandHandler(IAppDbContext db) : IRequestHandler<UpdateProductCommand> { public async Task Handle(UpdateProductCommand r,CancellationToken ct){ var p=await db.Products.FindAsync([r.Id],ct)??throw new KeyNotFoundException("Product not found."); if(p.IsDeleted) throw new KeyNotFoundException("Product not found."); if(await db.Products.AnyAsync(x=>x.SKU==r.SKU&&x.Id!=r.Id&&!x.IsDeleted,ct)) throw new InvalidOperationException("SKU already exists."); p.Name=r.Name; p.SKU=r.SKU; p.Barcode=r.Barcode; p.Description=r.Description; p.PurchasePrice=r.PurchasePrice; p.SellingPrice=r.SellingPrice; p.MinimumStock=r.MinimumStock; p.CategoryId=r.CategoryId; p.UpdatedAt=DateTime.UtcNow; await db.SaveChangesAsync(ct); } }
